create or alter procedure [dbo].[GenerateAllAssetTypeDisplayValues] AS BEGIN SET NOCOUNT ON; DECLARE @trancount int; SET @trancount = @@trancount; BEGIN TRY IF @trancount = 0 BEGIN TRANSACTION ELSE SAVE TRANSACTION usp_my_procedure_name;
--drop schemabound views that blocks truncating AssetDisplayValue drop view if exists workflow.ItemIssue drop view if exists workflow.ItemAsset
--delete by the asset type truncate table AssetDisplayValue;
--!IMPORTANT : make sure that this views match ones in [workflow].[ItemIssue] and [workflow].[ItemAsset] xml files in Environment scripts --rebuild [workflow].[ItemIssue] view exec ('create or alter view [workflow].[ItemIssue] WITH SCHEMABINDING as select wi.id as WorkFlowItemId, cast(substring(issue_dv.displayvalue,0,850) as nvarchar(850)) as AssetName from [workflow].[type] wt inner join [workflow].[version] wv on (wt.id = wv.typeid) inner join [workflow].[item] wi on (wv.id = wi.versionid) inner join [dbo].[issue] iss on wi.[objectid] = iss.id and wi.[object] = ''Issue'' inner join [dbo].[asset] cod on iss.objectid = cod.objectid and cod.[object] = iss.[object] inner join dbo.AssetDisplayValue issue_dv on issue_dv.assetid = cod.id;')
exec ('IF NOT EXISTS (select * from sys.indexes where name = ''CIX_WorkflowItemIssue'') BEGIN CREATE UNIQUE CLUSTERED INDEX CIX_WorkflowItemIssue ON [workflow].[ItemIssue](WorkFlowItemId); END
IF NOT EXISTS (select * from sys.indexes where name = ''IX_CIX_WorkflowItemIssue_AssetName'') BEGIN CREATE NONCLUSTERED INDEX IX_CIX_WorkflowItemIssue_AssetName ON [workflow].[ItemIssue](AssetName); END') --end rebuild [workflow].[ItemIssue] view
--rebuild [workflow].[ItemAsset] view exec ('create view [workflow].[ItemAsset] WITH SCHEMABINDING as select wi.id as WorkFlowItemId, cast(coalesce(substring(adv.displayvalue,0,850),''(unknown)'') as nvarchar(850)) as AssetName from [workflow].[type] wt inner join [workflow].[version] wv on (wt.id = wv.typeid) inner join [workflow].[item] wi on (wv.id = wi.versionid) inner join [dbo].asset ass on(ass.[object] = wi.[object] and ass.[objectid] = wi.[objectid]) inner join dbo.AssetDisplayValue adv on assetid = ass.id')
exec ('IF NOT EXISTS (select * from sys.indexes where name = ''CIX_WorkflowItemAsset'') BEGIN CREATE UNIQUE CLUSTERED INDEX CIX_WorkflowItemAsset ON [workflow].[ItemAsset](WorkFlowItemId); END
IF NOT EXISTS (select * from sys.indexes where name = ''IX_CIX_WorkflowItemAsset_AssetName'') BEGIN CREATE NONCLUSTERED INDEX IX_CIX_WorkflowItemAsset_AssetName ON [workflow].[ItemAsset](AssetName); END') --end rebuild [workflow].[ItemAsset] view
insert into AssetDisplayValue (AssetID, DisplayValue, DisplayValueHash, DisplayValuePrefix, UpdatedOn) select A.ID, ADV.DisplayValue, CONVERT(NVARCHAR(32),HashBytes('SHA1', ADV.DisplayValue),2) as DisplayValueHash, SUBSTRING(ADV.DisplayValue, 1, 250) as DisplayValuePrefix, getutcdate() from Asset A cross apply GetAssetDisplayValueByID(A.ID) ADV where ADV.DisplayValue is not null and A.[Object] not in( 'FusionAttribute')
lbexit: IF @trancount = 0 COMMIT; END TRY BEGIN CATCH DECLARE @error int, @message varchar(4000), @xstate int;
SELECT @error = ERROR_NUMBER(), @message = ERROR_MESSAGE(), @xstate = XACT_STATE();
IF @xstate = -1 ROLLBACK; IF @xstate = 1 AND @trancount = 0 ROLLBACK IF @xstate = 1 AND @trancount > 0 ROLLBACK TRANSACTION usp_my_procedure_name;
RAISERROR ('GenerateAllAssetTypeDisplayValues: %d: %s', 16, 1, @error, @message); END CATCH END

changeSet.rollback:

create or alter procedure [dbo].[GenerateAllAssetTypeDisplayValues]	
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @trancount int;
	SET @trancount = @@trancount;
	BEGIN TRY
    IF @trancount = 0
      BEGIN TRANSACTION
      ELSE
        SAVE TRANSACTION usp_my_procedure_name;

			--delete by the asset type
			delete from AssetDisplayValue;

			insert into AssetDisplayValue (AssetID, DisplayValue, DisplayValueHash, DisplayValuePrefix, UpdatedOn)
				select
					A.ID,
					ADV.DisplayValue,
					CONVERT(NVARCHAR(32),HashBytes('SHA1', ADV.DisplayValue),2) as DisplayValueHash,
					SUBSTRING(ADV.DisplayValue, 1, 250) as DisplayValuePrefix,
					getutcdate()
				from
					Asset A
					cross apply GetAssetDisplayValueByID(A.ID) ADV		
				where ADV.DisplayValue is not null and A.[Object] not in( 'FusionAttribute')	

		lbexit:
      IF @trancount = 0
      COMMIT;
  END TRY
  BEGIN CATCH
    DECLARE @error int,
            @message varchar(4000),
            @xstate int;

    SELECT
      @error = ERROR_NUMBER(),
      @message = ERROR_MESSAGE(),
      @xstate = XACT_STATE();

    IF @xstate = -1
      ROLLBACK;
    IF @xstate = 1 AND @trancount = 0
      ROLLBACK
    IF @xstate = 1 AND @trancount > 0
      ROLLBACK TRANSACTION usp_my_procedure_name;

    RAISERROR ('GenerateAllAssetTypeDisplayValues: %d: %s', 16, 1, @error, @message);
  END CATCH
END
